CREATE OR REPLACE FUNCTION data.fn_dict_changed_notify()
 RETURNS trigger
 LANGUAGE plpgsql
AS $$
BEGIN
  PERFORM pg_notify('bb_dict_changed', TG_TABLE_NAME);
  RETURN NULL;
END;
$$
;

CREATE TRIGGER trg_dict_changed_symbol
AFTER INSERT OR UPDATE OR DELETE ON data.symbol
FOR EACH STATEMENT EXECUTE FUNCTION data.fn_dict_changed_notify();

CREATE TRIGGER trg_dict_changed_coin
AFTER INSERT OR UPDATE OR DELETE ON data.coin
FOR EACH STATEMENT EXECUTE FUNCTION data.fn_dict_changed_notify();

CREATE TRIGGER trg_dict_changed_users
AFTER INSERT OR UPDATE OR DELETE ON data.users
FOR EACH STATEMENT EXECUTE FUNCTION data.fn_dict_changed_notify();

CREATE TRIGGER trg_common_log_changed
AFTER INSERT OR UPDATE ON data.common_log
FOR EACH STATEMENT EXECUTE FUNCTION data.fn_dict_changed_notify();
